from.util import parse_python_file, remove_comments, remove_docstring

class Tester():
    def __init__(self, file_name):
        self._file_name = file_name

    def parse(self):
        file_path = self._file_name

        source = parse_python_file(file_path)
        print("source")
        print(source)

        self._source_ast = ast.parse(source)
        print("ast")
        print(ast.dump(self._source_ast))

        self._func_ast = self._find_ast_func()
        print("func_ast")
        print(ast.dump(self._func_ast))

    def find_node_by_lineno(self, lineno):
        func_nodes = self._find_ast_func()
        node = None

        for child in ast.iter_child_nodes(func_nodes):
            if child.lineno == lineno:
                node = child
                break

        return node

    def get_fix_function(self):
        self.parse()
        # return self._source_ast
        return self._func_ast

    def _find_ast_func(self):
        func_nodes = []

        for node in ast.walk(self._source_ast):
            if isinstance(node, ast.FunctionDef):
                func_nodes.append(node)

        return func_nodes[0]

    def _remove_ast_func(self, func_ast):
        parent = func_ast.parent
        parent.body.remove(func_ast)
        return parent


